package com.bank.flink;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// A worker process with a fixed number of slots; slots run subtasks and hold state.
class TaskManager {
    private static final Logger log = Logger.getLogger(TaskManager.class.getName());

    final String id;
    final int numSlots;
    private final List<String> runningSubtasks = new ArrayList<>();
    private boolean alive = true;

    TaskManager(String id, int numSlots) { this.id = id; this.numSlots = numSlots; }

    int freeSlots() { return alive ? numSlots - runningSubtasks.size() : 0; }

    void deploy(String subtask) {
        runningSubtasks.add(subtask);
        log.info(() -> "TaskManager " + id + " running subtask " + subtask + " in a slot");
    }

    void snapshotState(long checkpointId) {
        if (alive) log.fine(() -> "TaskManager " + id + " snapshotted state for checkpoint " + checkpointId);
    }

    void crash() { alive = false; runningSubtasks.clear(); log.severe("TaskManager " + id + " CRASHED"); }
    boolean isAlive() { return alive; }
    List<String> subtasks() { return runningSubtasks; }
}
