package com.bank.flink;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Allocates TaskManager slots; under YARN/K8s it would spin up new TaskManagers on demand.
class ResourceManager {
    private static final Logger log = Logger.getLogger(ResourceManager.class.getName());

    private final List<TaskManager> taskManagers = new ArrayList<>();

    void registerTaskManager(TaskManager tm) {
        taskManagers.add(tm);
        log.info(() -> "ResourceManager registered " + tm.id + " with " + tm.numSlots + " slots");
    }

    // Return task managers with free slots to satisfy the requested parallelism.
    List<TaskManager> allocateSlots(int needed) {
        int available = taskManagers.stream().filter(TaskManager::isAlive).mapToInt(TaskManager::freeSlots).sum();
        if (available < needed) {
            log.info(() -> "Not enough slots (" + available + "<" + needed + ") — would request new TaskManagers from YARN/K8s");
        }
        log.info(() -> "ResourceManager allocating " + needed + " slots across live TaskManagers");
        return new ArrayList<>(taskManagers);
    }

    List<TaskManager> liveTaskManagers() { return taskManagers.stream().filter(TaskManager::isAlive).toList(); }
}
