package com.bank.flink;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// The per-job master: build ExecutionGraph, schedule, checkpoint, recover.
class JobManager {
    private static final Logger log = Logger.getLogger(JobManager.class.getName());

    private final JobGraph jobGraph;
    private final ResourceManager resourceManager;
    private long lastCheckpointId = 0;
    private List<String> subtasks = new ArrayList<>();

    JobManager(JobGraph jobGraph, ResourceManager resourceManager) {
        this.jobGraph = jobGraph;
        this.resourceManager = resourceManager;
    }

    // Convert JobGraph → ExecutionGraph (physical subtasks) and deploy.
    void runJob() {
        buildExecutionGraph();
        deploy();
        checkpoint(); // first checkpoint after startup
    }

    private void buildExecutionGraph() {
        subtasks = new ArrayList<>();
        for (String op : jobGraph.operators) {
            for (int p = 0; p < jobGraph.parallelism; p++) subtasks.add(op + "#" + p);
        }
        log.info(() -> "JobManager built ExecutionGraph: " + subtasks.size() + " subtasks ("
                + jobGraph.operators.size() + " operators × parallelism " + jobGraph.parallelism + ")");
    }

    private void deploy() {
        List<TaskManager> tms = resourceManager.allocateSlots(subtasks.size());
        int i = 0;
        for (String st : subtasks) {
            TaskManager tm = pickLiveWithSlot(tms);
            if (tm != null) tm.deploy(st);
            i++;
        }
        log.info(() -> "JobManager deployed all subtasks onto TaskManager slots");
    }

    private TaskManager pickLiveWithSlot(List<TaskManager> tms) {
        for (TaskManager tm : tms) if (tm.isAlive() && tm.freeSlots() > 0) return tm;
        return tms.stream().filter(TaskManager::isAlive).findFirst().orElse(null);
    }

    void checkpoint() {
        lastCheckpointId++;
        for (TaskManager tm : resourceManager.liveTaskManagers()) tm.snapshotState(lastCheckpointId);
        log.info(() -> "JobManager completed checkpoint " + lastCheckpointId + " (state snapshotted to durable storage)");
    }

    // Detect a failure and restore from the last completed checkpoint.
    void recoverFromFailure() {
        log.warning(() -> "JobManager detected TaskManager failure → restoring from checkpoint " + lastCheckpointId);
        deploy(); // re-request slots and redeploy subtasks
        log.info(() -> "JobManager restored job from checkpoint " + lastCheckpointId + " (no state lost)");
    }
}
