package com.bank.flink;

import java.util.logging.Logger;

// Entry point: receives job submissions over REST, serves the UI, spawns a JobManager per job.
class Dispatcher {
    private static final Logger log = Logger.getLogger(Dispatcher.class.getName());

    private final ResourceManager resourceManager;

    Dispatcher(ResourceManager resourceManager) { this.resourceManager = resourceManager; }

    JobManager submitJob(JobGraph jobGraph) {
        log.info(() -> "Dispatcher received job '" + jobGraph.jobName + "' via REST; dashboard now shows it");
        JobManager jm = new JobManager(jobGraph, resourceManager);
        log.info(() -> "Dispatcher spawned a dedicated JobManager for '" + jobGraph.jobName + "'");
        return jm;
    }
}
