package com.bank.flink;

import java.util.List;
import java.util.logging.Logger;

public class FlinkArchDemo {
    private static final Logger log = Logger.getLogger(FlinkArchDemo.class.getName());

    public static void main(String[] args) {
        // Cluster: ResourceManager with two TaskManagers (4 slots each).
        ResourceManager rm = new ResourceManager();
        TaskManager tm1 = new TaskManager("tm-1", 4);
        TaskManager tm2 = new TaskManager("tm-2", 4);
        rm.registerTaskManager(tm1);
        rm.registerTaskManager(tm2);

        // Submit a fraud-scoring streaming job through the Dispatcher.
        Dispatcher dispatcher = new Dispatcher(rm);
        JobGraph fraudJob = new JobGraph("realtime-fraud-scoring",
                List.of("txn-source", "keyBy-account", "fraud-score", "alert-sink"), 2);
        JobManager jm = dispatcher.submitJob(fraudJob);

        // Run: build plan → allocate slots → deploy → checkpoint.
        jm.runJob();
        jm.checkpoint(); // a periodic checkpoint while running

        // A worker crashes; JobManager recovers from the last checkpoint.
        log.info("=== Simulating a TaskManager crash ===");
        tm1.crash();
        jm.recoverFromFailure();
    }
}
